import{_ as t,o as s,c as a,ae as i}from"./chunks/framework.BajMXG5H.js";const p=JSON.parse('{"title":"What is Orchestra?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-orchestra.md","filePath":"guide/what-is-orchestra.md"}'),o={name:"guide/what-is-orchestra.md"};function n(r,e,l,h,c,d){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="what-is-orchestra" tabindex="-1">What is Orchestra? <a class="header-anchor" href="#what-is-orchestra" aria-label="Permalink to &quot;What is Orchestra?&quot;">​</a></h1><p>Orchestra is a macOS desktop application that monitors AI coding agent sessions in real-time. It integrates with <a href="https://claude.ai/code" target="_blank" rel="noreferrer">Claude Code</a> via Hooks to provide a unified dashboard for all your active coding sessions.</p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>When running multiple Claude Code sessions across different projects, it&#39;s hard to know:</p><ul><li>Which sessions are waiting for your input</li><li>Which sessions need permission approval</li><li>Which sessions have completed their tasks</li><li>Which sessions are running subagents or team operations</li></ul><p>You end up constantly switching between terminal windows to check status.</p><h2 id="the-solution" tabindex="-1">The Solution <a class="header-anchor" href="#the-solution" aria-label="Permalink to &quot;The Solution&quot;">​</a></h2><p>Orchestra sits in the background and watches all your Claude Code sessions through a single dashboard. When a session needs your attention, you get a notification with a one-click jump to that session.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Real-time Monitoring</strong> — See all sessions at a glance with live status updates</li><li><strong>Smart Cue System</strong> — Automatic alerts when sessions need input, permission, or have errors</li><li><strong>One-click Jump</strong> — Switch to any session via tmux + iTerm2 integration</li><li><strong>Grid &amp; List Views</strong> — Switch between grid and list layouts, with search and tmux session tabs</li><li><strong>Agent Badges</strong> — Identify which AI agent (Claude, Codex, Gemini, etc.) is running each session</li><li><strong>Team Mode</strong> — Detect and visualize Claude Code Agent Teams with rainbow-bordered cards</li><li><strong>Subagent Tracking</strong> — Track active subagent count per session</li><li><strong>Pomodoro Timer</strong> — Built-in focus timer with customizable work/break durations and cycle management</li><li><strong>Native macOS</strong> — Lightweight Tauri app with system notifications and sounds</li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude Code Hook → HTTP POST → Orchestra (port 3008) → Desktop UI</span></span>
<span class="line"><span>                                                      → System Notification</span></span>
<span class="line"><span>                                                      → Sound Alert</span></span></code></pre></div><ol><li>Claude Code fires hook events (PreToolUse, PostToolUse, Stop, SubagentStart, TeammateIdle, etc.)</li><li>Each event is sent via <code>curl</code> to Orchestra&#39;s local HTTP server on port 3008</li><li>Orchestra updates the session state and displays it in the desktop UI</li><li>When a session needs attention, a cue notification appears with a Jump button</li></ol>`,13)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
